    async def create_federation_active_directory(
        self,
        *,
        base_dn_for_groups: str,
        base_dn_for_users: str,
        domain_alias: str,
        domain_name: str,
        ip: str,
        password: str,
        service_name: str,
        username: str,
        description: str | None = None,
        ldap_hostname: str | None = None,
        ldap_tcp_port: int | None = None,
        no_ssl: bool | None = None,
        ssl_thumbprint: str | None = None,
    ) -> DedicatedCloudTask:
        """
        POST /1.0/dedicatedCloud/{serviceName}/federation/activeDirectory

        Create a federated Active Directory

        API status: DEPRECATED.

        Args:
            base_dn_for_groups: Active Directory base DN for groups, e.g.
                dc=example,dc=com
            base_dn_for_users: Active Directory base DN for users, e.g.
                dc=example,dc=com
            description: Description of your option access network
            domain_alias: Active Directory NetBIOS name, e.g. example
            domain_name: Active Directory domain name, e.g. example.com
            ip: IP address of the remote service, e.g. 123.100.200.0
            ldap_hostname: Active Directory LDAP hostname
            ldap_tcp_port: Active Directory LDAP/LDAPS TCP port (636 for LDAPS or 389
                for LDAP)
            no_ssl: Use unsecure LDAP instead of LDAPS
            password: Active Directory password
            service_name: Domain of the service
            ssl_thumbprint: SSL thumbprint of the remote service, e.g.
                A7:61:68:...:61:91:2F
            username: Active Directory user name (pre-Windows 2000 name), e.g.
                jdoe@example.com
        """
        data = await self._client.request_json(
            "POST",
            self._client.path(
                "/1.0/dedicatedCloud/{serviceName}/federation/activeDirectory",
                serviceName=service_name,
            ),
            body={
                "baseDnForGroups": base_dn_for_groups,
                "baseDnForUsers": base_dn_for_users,
                "description": description,
                "domainAlias": domain_alias,
                "domainName": domain_name,
                "ip": ip,
                "ldapHostname": ldap_hostname,
                "ldapTcpPort": ldap_tcp_port,
                "noSsl": no_ssl,
                "password": password,
                "sslThumbprint": ssl_thumbprint,
                "username": username,
            },
        )
        return DedicatedCloudTask.model_validate(data)

