    async def create_user(
        self,
        *,
        name: str,
        service_name: str,
        can_add_ressource: bool | None = None,
        can_manage_rights: bool | None = None,
        email: str | None = None,
        encryption_right: bool | None = None,
        expiration_date: datetime | None = None,
        first_name: str | None = None,
        last_name: str | None = None,
        network_role: DedicatedCloudRightNetworkRoleEnum | None = None,
        nsx_right: bool | None = None,
        password: str | None = None,
        phone_number: str | None = None,
        receive_alerts: bool | None = None,
        right: DedicatedCloudRightRightEnum | None = None,
        token_validator: bool | None = None,
        vm_network_role: DedicatedCloudRightVmNetworkRoleEnum | None = None,
    ) -> DedicatedCloudTask:
        """
        POST /1.0/dedicatedCloud/{serviceName}/user

        Create a user

        Args:
            can_add_ressource: Is this User able to add ressources in the Datacenter he
                has access ? (default is no right to add ressource)
            can_manage_rights: Is this user able to manage the users rights
            email: The user email. If this field is empty, user informations will be
                sent to the dedicatedCloud administrator contact.
            encryption_right: Defines if the user can manage encryption / KMS
                configuration
            expiration_date: Date of removal of the user.
            first_name: First name of the user
            last_name: Last name of the user
            name: Name of the user (login)
            network_role: Determine how this user will be able to act on this VMware on
                OVHcloud v(x)Lans
            nsx_right: Is this User able to access nsx interface (requires NSX option)
            password: The user password. It must fits your VMware on OVHcloud password
                policy. If this field is empty, a random password will be generated and
                sent by email.
            phone_number: Mobile phone number of the user
            receive_alerts: Defines if the user receives technical alerts
            right: Determine what kind of access the User will have in all Datacenters
                of your VMware on OVHcloud (default is disabled)
            service_name: Domain of the service
            token_validator: Defines if the user can confirm security tokens (if a
                compatible option is enabled)
            vm_network_role: Determine how this user will be able to act on this VMware
                on OVHcloud VM Network
        """
        data = await self._client.request_json(
            "POST",
            self._client.path(
                "/1.0/dedicatedCloud/{serviceName}/user", serviceName=service_name
            ),
            body={
                "canAddRessource": can_add_ressource,
                "canManageRights": can_manage_rights,
                "email": email,
                "encryptionRight": encryption_right,
                "expirationDate": expiration_date,
                "firstName": first_name,
                "lastName": last_name,
                "name": name,
                "networkRole": network_role,
                "nsxRight": nsx_right,
                "password": password,
                "phoneNumber": phone_number,
                "receiveAlerts": receive_alerts,
                "right": right,
                "tokenValidator": token_validator,
                "vmNetworkRole": vm_network_role,
            },
        )
        return DedicatedCloudTask.model_validate(data)

